rules:
.footer__newsletter-title {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: var(--ls-sub);
  color: var(--c-text-on-dark);
  line-height: 1.3;
}

.footer__newsletter-desc {
  font-size: var(--t-paragraph);
  color: var(--c-label-on-dark);
  line-height: var(--lh-row);
  display: none; /* mobile: Pencil tqbXr has NO desc — only title + email-pill + disclaimer */
}

.footer__email-form {
  display: flex;
  align-items: center;
  height: 48px;
  padding: 0 20px;
  background: var(--c-bg);
  border-radius: 100px;
}

.footer__email-form input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  font-size: 14px;
  color: var(--c-text);
  font-family: var(--font-primary);
}

.footer__email-form button {
  background: transparent;
  color: var(--c-text);
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  transition: transform var(--dur-short) var(--ease-swiss),
              opacity var(--dur-short) var(--ease-out);
}

.footer__disclaimer {
  font-size: 11px;
  color: #F5F3EF66; /* Pencil z46ZAu 40% on dark */
  line-height: 1.5;
}

.footer__bottom {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-top: 40px;
  padding-top: 24px;
  border-top: 1px solid var(--c-border-on-dark);
}

.footer__copyright--tertiary {
  font-size: 12px;
  color: #F5F3EF66; /* Pencil bPmBt 40% on dark */
}

.footer__legal {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 8px;
  margin-top: 8px;
}

.footer__bottom {
    flex-direction: row;
    justify-content: space-between;
    align-items: end;
    margin-top: 0;
    padding-top: 28px;
    gap: var(--s-5);
  }
